      pendingCandidates:candidates.items.filter(item => item.active && item.review).length,
      secondEngineConfigured,
      thirdEngineConfigured,
      searchEngines:1 + (secondEngineConfigured ? 1 : 0) + (thirdEngineConfigured ? 1 : 0),
