  };
  return portals[host] ? { name:portals[host][0],host,group:portals[host][1] } : null;
}

export function safePublicUrl(value:string, base?:string):string | null {
  try {
    if (typeof value!=='string' || value.length>2000) return null;
    const url = new URL(value, base);
    const host = url.hostname.toLowerCase();
    if (!host.includes('.') || host === 'localhost' || host.endsWith('.localhost') || host.endsWith('.local') ||
        host.startsWith('[') || /^(?:\d+\.){3}\d+$/.test(host)) return null;
    if (!['https:','http:'].includes(url.protocol) || url.username || url.password || url.port) return null;
    if ([...url.searchParams.keys()].some(key => /^(access_token|token|api_key|apikey|session|authorization)$/i.test(key))) return null;
    url.hash = '';
    for (const key of [...url.searchParams.keys()]) if (/^utm_/i.test(key) || ['fbclid','gclid','trk','trackingId'].includes(key)) url.searchParams.delete(key);
    url.searchParams.sort();
    return url.toString().length<=2000 ? url.toString() : null;
  } catch { return null; }
}

export function publicSourceAdapter(value:string):PublicAdapter | null {
  const clean = safePublicUrl(value);
  if (!clean) return null;
  const url = new URL(clean), host = url.hostname.replace(/^www\./,'');
  let name = '', identityUrl = '', family:PublicAdapter['family'] = 'portal';
  let match:RegExpMatchArray | null;
  if (['bne.gob.cl','bne.cl'].includes(host) && (match=url.pathname.match(/^\/oferta\/(20\d{2}-\d{1,9})\/?$/))) {
    name='Bolsa Nacional de Empleo';identityUrl='https://www.bne.gob.cl/oferta/'+match[1];
  } else if (host === 'portal.chiletrabajos.cl' && (match=url.pathname.match(/^\/empresa\/[^/]+\/trabajo\/([^/]+)\/?$/))) {
    name = 'Chiletrabajos'; identityUrl = 'https://www.chiletrabajos.cl/trabajo/'+match[1];
  } else if (host === 'chiletrabajos.cl' && /^\/trabajo\/[^/]+\/?$/.test(url.pathname)) {
    name = 'Chiletrabajos'; identityUrl = 'https://www.chiletrabajos.cl'+url.pathname.replace(/\/$/,'');
  } else if (['indeed.com','cl.indeed.com'].includes(host) && ['/viewjob','/rc/clk'].includes(url.pathname) && /^[a-f0-9]{16}$/i.test(url.searchParams.get('jk') || '')) {
    name = 'Indeed'; identityUrl = 'https://cl.indeed.com/viewjob?jk='+url.searchParams.get('jk')!.toLowerCase();
  } else if (['cl.computrabajo.com','computrabajo.cl'].includes(host) && (match = url.pathname.match(/^\/ofertas-de-trabajo\/(oferta-de-trabajo-de-[^/]+)\/?$/))) {
    name = 'Computrabajo'; identityUrl = 'https://cl.computrabajo.com/ofertas-de-trabajo/'+match[1];
  } else if (['linkedin.com','cl.linkedin.com','es.linkedin.com'].includes(host) && (match = url.pathname.match(/^\/jobs\/view\/(?:[^/]*-)?(\d{6,})\/?$/))) {
    name = 'LinkedIn'; identityUrl = 'https://www.linkedin.com/jobs/view/'+match[1];
  } else if (host === 'laborum.cl' && (match = url.pathname.match(/^\/empleos\/[^/]+-(\d{5,})\.html\/?$/))) {
    name = 'Laborum'; identityUrl = 'https://www.laborum.cl/empleos/oferta-'+match[1]+'.html';
  } else if (host==='kitempleo.cl' && (match=url.pathname.match(/^\/empleo\/(\d{5,})\/[^/]+\/?$/))) {
    name='Kit Empleo';family='aggregator';identityUrl='https://www.kitempleo.cl/empleo/'+match[1];
  } else if (host === 'opcionempleo.cl' && (match = url.pathname.match(/^\/jobad\/([a-z0-9]{12,})(?:\.html)?\/?$/i))) {
    name = 'Opción Empleo'; family = 'aggregator'; identityUrl = 'https://www.opcionempleo.cl/jobad/'+match[1].toLowerCase();
  } else if (host==='jobs.arauco.com' && (match=url.pathname.match(/^\/(?:Chile\/)?job\/(?:[^/]+\/)?(\d{5,})\/?$/i))) {
    name='Arauco · portal de empleo';identityUrl='https://jobs.arauco.com/job/'+match[1];
  } else if (host==='cmpc.csod.com' && (match=url.pathname.match(/^\/ux\/ats\/careersite\/4\/home\/requisition\/(\d{1,9})\/?$/)) && url.searchParams.get('c')==='cmpc' && [...url.searchParams.keys()].every(key=>key==='c')) {
    name='CMPC · portal de empleo';identityUrl='https://cmpc.csod.com/ux/ats/careersite/4/home/requisition/'+match[1]+'?c=cmpc';
  } else if (LOCAL_PUBLISHERS[host] && host!=='wof-chile.com' && url.pathname.split('/').filter(Boolean).length &&
      !/^\/(?:noticias?|concursos-publicos|concursos-disponibles|llamados-a-concurso-20\d{2}|trabaja-con-nosotros|direccion-de-fomento-productivo|category(?:\/[^/]+)?|categoria(?:\/[^/]+)?|tag(?:\/[^/]+)?|page(?:\/\d+)?|wp-json|feed)(?:\/\d+)?\/?$/.test(url.pathname) && !url.search) {
    name = LOCAL_PUBLISHERS[host]; family = 'local'; identityUrl = 'https://'+host+url.pathname.replace(/\/$/,'');
  }
  return name ? { name, family, identityUrl, verificationMethod:name+(host==='cmpc.csod.com'?' public career page + official requisition response':name==='Bolsa Nacional de Empleo'?' individual page + official labelled offer':' individual page + matching JobPosting') } : null;
}

export function samePublicJob(left:string, right:string) {
  const first = publicSourceAdapter(left), second = publicSourceAdapter(right);
  return Boolean(first && second && first.identityUrl === second.identityUrl);
}

// Keep legacy URL identities unchanged. Several reviewed jobs may share a document.
export function publicOfferIdentity(value:string, documentKey?:string):string | null {
  const adapter=publicSourceAdapter(value);
  if (!adapter || adapter.family==='aggregator') return null;
  if (documentKey===undefined) return adapter.identityUrl;
  if (adapter.family!=='local' || typeof documentKey!=='string' || !/^[a-f0-9]{64}$/.test(documentKey)) return null;
  return adapter.identityUrl+'\0document-unit-v1\0'+documentKey;
}

// Feed-only equivalence: preserve ingestion keys and source records unchanged.
export function publicFeedIdentity(value:string, documentKey?:string):string | null {
  if (documentKey!==undefined) return publicOfferIdentity(value,documentKey);
  const clean=safePublicUrl(value);
  if (!clean) return null;
  const url=new URL(clean),host=url.hostname.replace(/^www\./,'');
  const path=host==='portal.chiletrabajos.cl'
    ? url.pathname.match(/^\/empresa\/[^/]+\/trabajo\/([^/]+)\/?$/)?.[1]
    : host==='chiletrabajos.cl' ? url.pathname.match(/^\/trabajo\/([^/]+)\/?$/)?.[1] : null;
  const id=path?.match(/(?:^|-)(\d{5,12})$/)?.[1];
  return id ? 'https://www.chiletrabajos.cl/trabajo/'+id : publicOfferIdentity(clean);
}

export function publicJobExclusion(item:Record<string,unknown>):string | null {
  if (item.kind!=='job_offer') return null;
  const clean=typeof item.url==='string' ? safePublicUrl(item.url) : null;
  if (!clean) return 'original_individual_url_missing';
  const url=new URL(clean),host=url.hostname.replace(/^www\./,'');
  if (['chiletrabajos.cl','portal.chiletrabajos.cl'].includes(host) && !publicFeedIdentity(clean)) {
    return 'portal_index_not_individual_offer';
  }
  const publisher=publicPublisher(clean),adapter=publicSourceAdapter(clean);
  if (publisher && !adapter && !publicFeedIdentity(clean)) return 'portal_index_not_individual_offer';
  if (adapter?.family==='aggregator') return 'aggregator_requires_primary_source';
  const title=String(item.title || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  if (/^(?:angol|lumaco|los sauces|traiguen|renaico|nacimiento|negrete|mulchen|collipulli|victoria|puren|ercilla|talca|temuco|pozo almonte|los angeles)\s*$/.test(title)) {
    return 'place_name_is_not_a_job_title';
  }
  const explicit=title.match(/\bcomuna\s+(?:de\s+)?(los angeles|los sauces|angol|lumaco|traiguen|renaico|nacimiento|negrete|mulchen|collipulli|victoria|puren|ercilla|temuco)\b/)?.[1];
  const recorded=Array.isArray(item.workCommunes) ? item.workCommunes.map(value=>String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()) : [];
  if (explicit && !recorded.includes(explicit)) return 'workplace_conflicts_with_explicit_job_title';
  if (Array.isArray(item.workCommunes) && item.workCommunes.includes('Victoria')) {
    const path=url.pathname.toLowerCase().replace(/-/g,' ');
    const confirmedBrand=/victoria\s+s\s+secret/.test(path);
    const context=(confirmedBrand ? title.replace(/victoria\s*[’'´`]?\s*s(?=&#8230;|…|$)/g,'') : title)+' '+path;
    const stripped=context.replace(/victoria\s*[’'´`]?\s*s\s+secret/g,'').replace(/nueva\s+victoria/g,'');
    if (stripped!==context && !/\bvictoria\b/.test(stripped)) return 'brand_or_remote_site_is_not_victoria_commune';
  }
  return null;
}

import { Buffer } from 'node:buffer';
import { publicPublisher, safePublicUrl, samePublicJob } from './public-source-adapters';
import { checkPublicRobots } from './public-robots';

export type PublicPage = { url:string; status:number; raw:string; mime:string; bytes:number; robots?:{http:number;url:string;nextRetryAt?:string}; error?:string };

export async function fetchPublicPage(value:string, expectedJob?:string):Promise<PublicPage> {
  const clean = safePublicUrl(value), publisher = publicPublisher(value);
  if (!clean || !publisher) return { url:value,status:0,raw:'',mime:'',bytes:0,error:'publisher_not_allowed' };
  if (new URL(clean).protocol !== 'https:') return { url:value,status:0,raw:'',mime:'',bytes:0,error:'https_required' };
  const signal = AbortSignal.timeout(6500);
  let current = clean;
  try {
    for (let redirect=0;redirect<4;redirect++) {
      const policy=await checkPublicRobots(current);
      if (!policy.allowed) return {url:current,status:0,raw:'',mime:'',bytes:0,error:policy.error,robots:{http:policy.robotsHttp||0,url:policy.robotsUrl||new URL(current).origin+'/robots.txt',nextRetryAt:policy.nextRetryAt}};
      const response = await fetch(current,{ headers:{ 'user-agent':'TrabajoCercaPublic/1.0','accept':'text/html,application/xhtml+xml,application/rss+xml,application/xml' },redirect:'manual',signal });
      if ([301,302,303,307,308].includes(response.status)) {
        const next = safePublicUrl(response.headers.get('location') || '',current);
        await response.body?.cancel();
        if (!next || new URL(next).protocol !== 'https:' || publicPublisher(next)?.group !== publisher.group || (expectedJob && !samePublicJob(expectedJob,next))) return { url:current,status:response.status,raw:'',mime:'',bytes:0,error:'redirect_identity_unconfirmed' };
        current = next;continue;
      }
      const mime = (response.headers.get('content-type') || '').split(';')[0].toLowerCase();
      if (response.status!==200) { await response.body?.cancel();return { url:current,status:response.status,raw:'',mime,bytes:0 }; }
      if (!['text/html','application/xhtml+xml','application/rss+xml','application/xml','text/xml'].includes(mime)) {
        await response.body?.cancel();return { url:current,status:200,raw:'',mime,bytes:0,error:'document_requires_local_reader' };
      }
      const reader = response.body?.getReader();
      const parts:Uint8Array[] = [];
      let bytes = 0;
      if (reader) {
        while (true) {
          const chunk = await reader.read();if (chunk.done) break;
          bytes += chunk.value.byteLength;
          if (bytes>600000) { await reader.cancel();return { url:current,status:200,raw:'',mime,bytes,error:'source_byte_budget_exceeded' }; }
          parts.push(chunk.value);
        }
      } else {
        const raw = new Uint8Array(await response.arrayBuffer());bytes = raw.byteLength;
        if (bytes>600000) return { url:current,status:200,raw:'',mime,bytes,error:'source_byte_budget_exceeded' };
        parts.push(raw);
      }
      const buffer=Buffer.concat(parts);
      const declared=(response.headers.get('content-type') || '').match(/charset\s*=\s*["']?([^\s;"']+)/i)?.[1]?.toLowerCase();
      const meta=buffer.subarray(0,4096).toString('ascii').match(/charset\s*=\s*["']?([a-z0-9_-]+)/i)?.[1]?.toLowerCase();
      const encoding=declared || meta || 'utf-8';
      if (!['utf-8','utf8','iso-8859-1','latin1','windows-1252'].includes(encoding)) return { url:current,status:200,raw:'',mime,bytes,error:'source_encoding_unsupported' };
      const raw=new TextDecoder(encoding==='utf8'?'utf-8':encoding).decode(buffer);
      const accessText=raw.replace(/<script\b[\s\S]*?<\/script>|<style\b[\s\S]*?<\/style>/gi,'').replace(/<[^>]+>/g,' ');
      if (/verify you are human|unusual traffic|verificaci[oó]n requerida|tr[aá]fico inusual|verifica si realmente|no (?:es|eres) un robot/i.test(accessText)) {
        return {url:current,status:200,raw,mime,bytes,error:'public_access_challenge'};
      }
      return { url:current,status:200,raw,mime,bytes };
    }
    return { url:current,status:0,raw:'',mime:'',bytes:0,error:'redirect_budget_exhausted' };
  } catch {
    return { url:current,status:0,raw:'',mime:'',bytes:0,error:signal.aborted?'source_timeout':'source_unavailable' };
  }
}

import { Buffer } from 'node:buffer';
import { createHash } from 'node:crypto';
import { publicPublisher, safePublicUrl } from './public-source-adapters';
const PUBLIC_CRAWLER='TrabajoCercaPublic/1.0';
type Policy={checkedAt:number;raw:string;error?:string;url:string;status:number;sha256?:string};
const publicPolicies=new Map<string,Policy>();

export function publicRobotsAllow(raw:string,address:string) {
  const groups:Array<{agents:string[];rules:Array<{path:string;allow:boolean}>}>=[];
  let group:{agents:string[];rules:Array<{path:string;allow:boolean}>} | null=null;
  let hasRules=false;
  for (const line of raw.split(/\r?\n/)) {
    const clean=line.replace(/#.*$/,'').trim(),colon=clean.indexOf(':');
    if (colon<0) continue;
    const key=clean.slice(0,colon).trim().toLowerCase(),value=clean.slice(colon+1).trim();
    if (key==='user-agent') {
      if (!group || hasRules) {group={agents:[],rules:[]};groups.push(group);hasRules=false;}
      group.agents.push(value.toLowerCase());
    } else if (group && ['allow','disallow'].includes(key)) {hasRules=true;if(value)group.rules.push({path:value,allow:key==='allow'});}
  }
  const scores=groups.map(value=>Math.max(-1,...value.agents.map(agent=>agent==='*'?0:PUBLIC_CRAWLER.toLowerCase().startsWith(agent)?agent.length:-1)));
  const best=Math.max(-1,...scores),url=new URL(address),path=url.pathname+url.search;
  const matches:Array<{allow:boolean;length:number}>=[];
  groups.forEach((value,index)=>{
    if (best<0 || scores[index]!==best) return;
    for (const rule of value.rules) {
      const end=rule.path.endsWith('$'),part=end?rule.path.slice(0,-1):rule.path;
      const pattern=part.split('*').map(text=>text.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('.*');
      if (new RegExp('^'+pattern+(end?'$':'')).test(path)) matches.push({allow:rule.allow,length:rule.path.replace(/[*$]/g,'').length});
    }
  });
  matches.sort((a,b)=>b.length-a.length || Number(b.allow)-Number(a.allow));
  return !matches.length || matches[0].allow;
}

const policyReads=new Map<string,Promise<Policy>>();
function policyTtl(policy:Policy) {
  if(!policy.error)return 3600000;
  return [401,403,429].includes(policy.status)?12*3600000:120000;
}
async function loadPolicy(origin:string,publisher:{group:string},now:number):Promise<Policy> {
  let url=origin+'/robots.txt';
  const policy:Policy={checkedAt:now,raw:'',url,status:0,error:'robots_policy_unavailable'};
  try {
    for(let hop=0;hop<4;hop++) {
      const response=await fetch(url,{redirect:'manual',signal:AbortSignal.timeout(6500),
        headers:{'user-agent':PUBLIC_CRAWLER,accept:'text/plain,text/html'}});
      policy.url=url;policy.status=response.status;
      if([301,302,303,307,308].includes(response.status)) {
        const next=safePublicUrl(response.headers.get('location')||'',url);
        await response.body?.cancel();
        if(!next||!next.startsWith('https:')||publicPublisher(next)?.group!==publisher.group)break;
        url=next;continue;
      }
      if(response.status===404){await response.body?.cancel();policy.error=undefined;break;}
      if(response.status!==200){await response.body?.cancel();break;}
      const reader=response.body?.getReader(),parts:Uint8Array[]=[];let size=0;
      if(reader)for(;;){
        const chunk=await reader.read();if(chunk.done)break;
        size+=chunk.value.byteLength;
        if(size>50000){await reader.cancel();throw new Error('policy_byte_limit');}
        parts.push(chunk.value);
      }
      else {
        const body=new Uint8Array(await response.arrayBuffer());
        if(body.length>50000)throw new Error('policy_byte_limit');
        parts.push(body);
      }
      const data=Buffer.concat(parts),mime=(response.headers.get('content-type')||'').split(';')[0].toLowerCase();
      policy.sha256=createHash('sha256').update(data).digest('hex');policy.raw=data.toString('utf8');
      if(mime!=='text/plain'&&!(mime==='text/html'&&/^\s*user-agent\s*:/im.test(policy.raw)))break;
      policy.error=undefined;break;
    }
  }catch{/* Unreadable policy never grants access to content. */}
  return policy;
}
export async function checkPublicRobots(address:string,now=Date.now()) {
  const origin=new URL(address).origin,publisher=publicPublisher(address);
  if(!publisher)return {allowed:false,error:'publisher_not_allowed'};
  let policy=publicPolicies.get(origin);
  if(!policy||now-policy.checkedAt>=policyTtl(policy)){
    let reading=policyReads.get(origin);
    if(!reading){
      reading=loadPolicy(origin,publisher,now).finally(()=>policyReads.delete(origin));
      policyReads.set(origin,reading);
    }
    policy=await reading;
    if(publicPolicies.size>=64&&!publicPolicies.has(origin))publicPolicies.delete(publicPolicies.keys().next().value!);
    publicPolicies.set(origin,policy);
  }
  const allowed=!policy.error&&publicRobotsAllow(policy.raw,address);
  return {allowed,error:policy.error||(allowed?undefined:'robots_disallowed'),
    robotsUrl:policy.url,robotsHttp:policy.status,robotsSha256:policy.sha256,
    checkedAt:new Date(policy.checkedAt).toISOString(),nextRetryAt:new Date(policy.checkedAt+policyTtl(policy)).toISOString()};
}

type Item = { id:string; [key:string]:unknown };
type Page = { items:Item[]; nextCursor?:string | null; totalItems?:number; totalJobOffers?:number; complete?:boolean; degraded?:boolean };
type Read = (path:string) => Promise<{ data:Page }>;

// Read every page through the frontend SDK; finding expected IDs is not a stop condition.
export async function readFeedInventory(read:Read, maxPages=100) {
  const items:Item[] = [];
  const ids = new Set<string>(), cursors = new Set<string>();
  let cursor:string | undefined, pagesRead=0, totalItems:number | undefined;
  let totalJobOffers:number | undefined;
  try {
    if (!Number.isInteger(maxPages) || maxPages<1 || maxPages>100) throw new Error('invalid_limit');
    while (pagesRead<maxPages) {
      const suffix=cursor ? '&cursor='+encodeURIComponent(cursor) : '';
      const { data }=await read('/api/listings?fresh=1'+suffix);
      if (!Array.isArray(data.items)) throw new Error('invalid_items');
      if (data.complete===false || data.degraded) throw new Error('partial_public_catalog');
      if (pagesRead===0) { totalItems=data.totalItems;totalJobOffers=data.totalJobOffers; }
      pagesRead++;
      for (const item of data.items) {
        if (typeof item.id!=='string' || !item.id || ids.has(item.id)) throw new Error('duplicate_or_invalid_id');
        ids.add(item.id);
        const { id,kind,title,company,source,workLocation,workCommunes,date,createdAt,url,verified,review,
          verifiedAt,verificationMethod,verificationReason,documentUnitKey,documentUnitVerified,sourcePublishedAt,sourceValidThrough,expiresAt,applicationUrl,applicationMethod,firstPublishedAt,lastVerifiedAt,externalVerifiedAt,revalidationDue,active,closureReason }=item;
        items.push({ id,kind,title,company,source,workLocation,workCommunes,date,createdAt,url,verified,review,
          verifiedAt,verificationMethod,verificationReason,documentUnitKey,documentUnitVerified,sourcePublishedAt,sourceValidThrough,expiresAt,applicationUrl,applicationMethod,firstPublishedAt,lastVerifiedAt,externalVerifiedAt,revalidationDue,active,closureReason });
      }
      if (!data.nextCursor) {
        if (totalItems!==undefined && (!Number.isSafeInteger(totalItems) || totalItems!==items.length)) throw new Error('incomplete_count');
        return { items,pagesRead,totalItems,totalJobOffers,complete:true,error:null };
      }
      if (typeof data.nextCursor!=='string' || cursors.has(data.nextCursor)) throw new Error('repeated_or_invalid_cursor');
      cursors.add(data.nextCursor);cursor=data.nextCursor;
    }
    throw new Error('page_limit_reached');
  } catch {
    return { items,pagesRead,totalItems,totalJobOffers,complete:false,error:'No se pudo completar la lectura de todas las páginas del feed.' };
  }
}

